try:
    import numpy as np
    anomaly_records = []
    for col in num_cols:
        series = df[col].dropna()
        if series.nunique() < 5:
            continue
        skew = float(series.skew())
        if abs(skew) > 2:
            shift = max(0, -series.min() + 1e-9)
            transformed = np.log1p(series + shift)
        else:
            transformed = series.copy()
            shift = 0
        q1 = transformed.quantile(0.25)
        q3 = transformed.quantile(0.75)
        iqr = q3 - q1
        lo3 = q1 - 3 * iqr
        hi3 = q3 + 3 * iqr
        lo4 = q1 - 4 * iqr
        hi4 = q3 + 4 * iqr
        lo5 = q1 - 5 * iqr
        hi5 = q3 + 5 * iqr
        mask = (transformed < lo3) | (transformed > hi3)
        flagged_pct = mask.sum() / len(series)
        if flagged_pct > 0.05:
            anomaly_records.append({
                'column': col,
                'row_index': None,
                'value': None,
                'expected_range': f'heavy-tailed distribution',
                'severity': 'low',
                'explanation': f'{col} flags more than 5% of values as extreme; treated as heavy-tailed natural distribution'
            })
            continue
        if abs(skew) > 2:
            lo3_orig = float(np.expm1(lo3) - shift)
            hi3_orig = float(np.expm1(hi3) - shift)
            lo4_orig = float(np.expm1(lo4) - shift)
            hi4_orig = float(np.expm1(hi4) - shift)
            lo5_orig = float(np.expm1(lo5) - shift)
            hi5_orig = float(np.expm1(hi5) - shift)
        else:
            lo3_orig, hi3_orig = float(lo3), float(hi3)
            lo4_orig, hi4_orig = float(lo4), float(hi4)
            lo5_orig, hi5_orig = float(lo5), float(hi5)
        flagged_idx = transformed[mask].index
        for idx in flagged_idx:
            val = float(df.loc[idx, col])
            t_val = float(transformed.loc[idx])
            if t_val > hi5 or t_val < lo5:
                sev = 'critical'
            elif t_val > hi4 or t_val < lo4:
                sev = 'high'
            else:
                sev = 'medium'
            exp_range = f'[{lo3_orig:.4g}, {hi3_orig:.4g}]'
            anomaly_records.append({
                'column': col,
                'row_index': int(idx),
                'value': val,
                'expected_range': exp_range,
                'severity': sev,
                'explanation': f'{col} value {val} lies outside expected range {exp_range}'
            })
    anomaly_records = anomaly_records[:25]
    result['anomalies'] = anomaly_records
except Exception:
    pass

