                sev = 'high'
            else:
                sev = 'medium'
            exp_range = f'[{lo3_orig:.4g}, {hi3_orig:.4g}]'
            anomaly_records.append({
                'column': col,
                'row_index': int(idx),
                'value': val,
                'expected_range': exp_range,
                'severity': sev,
                'explanation': f'{col} value {val} lies outside expected range {exp_range}'
            })
    anomaly_records = anomaly_records[:25]
    result['anomalies'] = anomaly_records
