try:
    import numpy as np
    from scipy import stats as sp_stats
    anomaly_list = []
    cap = 25
    for col in ['revenue', 'units', 'discount', 'marketing_spend']:
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = max(0, -s.min() + 1e-9)
            vals = np.log1p(s + shift)
        else:
            vals = s.copy()
            shift = 0.0
        q1, q3 = float(vals.quantile(0.25)), float(vals.quantile(0.75))
        iqr = q3 - q1
        lo3, hi3 = q1 - 3*iqr, q3 + 3*iqr
        lo4, hi4 = q1 - 4*iqr, q3 + 4*iqr
        lo5, hi5 = q1 - 5*iqr, q3 + 5*iqr
        mask = (vals < lo3) | (vals > hi3)
        flagged = mask.sum()
        if flagged / len(s) > 0.05:
            anomaly_list.append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': f'[{float(np.expm1(lo3) - shift):.4g}, {float(np.expm1(hi3) - shift):.4g}]' if abs(skew) > 2 else f'[{lo3:.4g}, {hi3:.4g}]',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; extreme-value flagging skipped'
            })
            continue
        idxs = vals[mask].index.tolist()
        for idx in idxs:
            if cap <= 0:
                break
            raw_val = float(df.loc[idx, col])
            tv = float(vals.loc[idx])
            if abs(skew) > 2:
                lo_orig = float(np.expm1(lo3) - shift)
                hi_orig = float(np.expm1(hi3) - shift)
            else:
                lo_orig, hi_orig = lo3, hi3
            exp_range = f'[{lo_orig:.4g}, {hi_orig:.4g}]'
            if tv > hi5 or tv < lo5:
                sev = 'critical'
            elif tv > hi4 or tv < lo4:
                sev = 'high'
            else:
                sev = 'medium'
            anomaly_list.append({
                'column': col, 'row_index': int(idx), 'value': raw_val,
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'{col} value {raw_val} lies outside expected range {exp_range}'
            })
            cap -= 1
    result['anomalies'] = anomaly_list
except Exception:
    pass

