try:
    import numpy as np
    anomaly_records = []
    skip_cols = set()
    for col in ['revenue', 'units', 'discount', 'marketing_spend']:
        s = df[col].dropna()
        if s.nunique() < 5:
            skip_cols.add(col)
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = max(0, -s.min() + 1)
            vals = np.log1p(s + shift)
        else:
            vals = s.copy()
            shift = 0
        q1, q3 = float(vals.quantile(0.25)), float(vals.quantile(0.75))
        iqr = q3 - q1
        lo3, hi3 = q1 - 3*iqr, q3 + 3*iqr
        lo4, hi4 = q1 - 4*iqr, q3 + 4*iqr
        lo5, hi5 = q1 - 5*iqr, q3 + 5*iqr
        mask = (vals < lo3) | (vals > hi3)
        frac = mask.sum() / len(vals)
        if frac > 0.05:
            anomaly_records.append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': f'{float(s.quantile(0.25)):.3g} to {float(s.quantile(0.75)):.3g}',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; extreme-value flagging skipped'
            })
            continue
        orig_lo = float(np.expm1(lo3) - shift) if abs(skew) > 2 else float(lo3)
        orig_hi = float(np.expm1(hi3) - shift) if abs(skew) > 2 else float(hi3)
        flagged_idx = vals[mask].index.tolist()
        for idx in flagged_idx:
            raw_val = float(df.loc[idx, col])
            tv = float(vals.loc[idx])
            if tv > hi5 or tv < lo5:
                sev = 'critical'
            elif tv > hi4 or tv < lo4:
                sev = 'high'
            else:
                sev = 'medium'
            exp_range = f'{orig_lo:.4g} to {orig_hi:.4g}'
            anomaly_records.append({
                'column': col, 'row_index': int(idx), 'value': raw_val,
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'{col} value {raw_val} lies outside expected range {exp_range}'
            })
    anomaly_records = anomaly_records[:25]
    result['anomalies'] = anomaly_records
except Exception:
    pass

