try:
    import numpy as np
    from scipy import stats as sp_stats
    skip_cols = {'order_id'}
    anomaly_records = []
    for col in metrics:
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = max(0, -s.min() + 1e-9)
            s_t = np.log1p(s + shift)
        else:
            s_t = s.copy()
            shift = 0
        Q1, Q3 = s_t.quantile(0.25), s_t.quantile(0.75)
        IQR = Q3 - Q1
        lo3, hi3 = Q1 - 3*IQR, Q3 + 3*IQR
        lo4, hi4 = Q1 - 4*IQR, Q3 + 4*IQR
        lo5, hi5 = Q1 - 5*IQR, Q3 + 5*IQR
        mask = (s_t < lo3) | (s_t > hi3)
        frac = mask.sum() / len(s_t)
        if frac > 0.05:
            result['anomalies'].append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': f'[{float(s.min()):.4g}, {float(s.max()):.4g}]',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; extreme-boundary flags exceed 5% of values, column skipped for individual anomalies'
            })
            continue
        if abs(skew) > 2:
            lo3_orig = float(np.expm1(lo3) - shift)
            hi3_orig = float(np.expm1(hi3) - shift)
        else:
            lo3_orig, hi3_orig = float(lo3), float(hi3)
        flagged = s_t[mask]
        for idx in flagged.index:
            orig_val = float(df.loc[idx, col])
            t_val = float(s_t.loc[idx])
            if t_val < lo5 or t_val > hi5:
                sev = 'critical'
            elif t_val < lo4 or t_val > hi4:
                sev = 'high'
            else:
                sev = 'medium'
            exp_range = f'[{lo3_orig:.4g}, {hi3_orig:.4g}]'
            anomaly_records.append({
                'column': col, 'row_index': int(idx), 'value': orig_val,
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'{col} value {orig_val} lies outside expected range {exp_range}'
            })
        if len(anomaly_records) >= 25:
            break
    result['anomalies'].extend(anomaly_records[:25])
except Exception:
    pass

