try:
    import numpy as np
    from scipy import stats as sp_stats
    anomalies = []
    skip_cols = {'order_id'}
    for col in numeric_cols:
        if col in skip_cols:
            continue
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = max(0, -s.min() + 1)
            vals = np.log1p(s + shift)
        else:
            vals = s.copy()
            shift = 0
        q1, q3 = vals.quantile(0.25), vals.quantile(0.75)
        iqr = q3 - q1
        lo3, hi3 = q1 - 3 * iqr, q3 + 3 * iqr
        lo4, hi4 = q1 - 4 * iqr, q3 + 4 * iqr
        lo5, hi5 = q1 - 5 * iqr, q3 + 5 * iqr
        mask = (vals < lo3) | (vals > hi3)
        if mask.sum() / len(vals) > 0.05:
            anomalies.append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': f'heavy-tailed distribution',
                'severity': 'low',
                'explanation': f'Column {col} has >5% extreme values; heavy-tailed distribution, not flagged individually'
            })
            continue
        if abs(skew) > 2:
            orig_lo = float(np.expm1(lo3) - shift)
            orig_hi = float(np.expm1(hi3) - shift)
        else:
            orig_lo, orig_hi = float(lo3), float(hi3)
        flagged = vals[mask]
        for idx in flagged.index:
            v_trans = vals.loc[idx]
            v_orig = float(df[col].loc[idx])
            if v_trans > hi5 or v_trans < lo5:
                sev = 'critical'
            elif v_trans > hi4 or v_trans < lo4:
                sev = 'high'
            else:
                sev = 'medium'
            exp_range = f'[{orig_lo:.4g}, {orig_hi:.4g}]'
            anomalies.append({
                'column': col, 'row_index': int(idx), 'value': v_orig,
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'Value {v_orig} in column {col} lies outside expected range {exp_range}'
            })
            if len(anomalies) >= 25:
                break
        if len(anomalies) >= 25:
            break
    result['anomalies'] = anomalies
except Exception:
    pass

