try:
    import numpy as np
    df['order_date'] = pd.to_datetime(df['order_date'])
    df['_ym'] = df['order_date'].dt.to_period('M')
    monthly_rev = df.groupby('_ym')['revenue'].sum().sort_index()
    if len(monthly_rev) >= 3:
        x = np.arange(len(monthly_rev))
        y = monthly_rev.values.astype(float)
        slope, intercept = np.polyfit(x, y, 1)
        last_period = monthly_rev.index[-1]
        next_period = last_period + 1
        next_val = float(slope * len(monthly_rev) + intercept)
        result['forecast_points'].append({'period': str(next_period), 'value': round(next_val, 2)})
        next2_val = float(slope * (len(monthly_rev) + 1) + intercept)
        result['forecast_points'].append({'period': str(next_period + 1), 'value': round(next2_val, 2)})
except Exception:
    pass

